<div class="row g-3"><div class="col-xl-8"><x-card type="primary" title="Nội dung dịch vụ"><x-input name="name" label="Tên dịch vụ" :value="$service->name" required /><x-input name="slug" label="Slug" :value="$service->slug" required /><x-textarea name="description" label="Mô tả ngắn" :value="$service->description" rows="3" /><x-textarea name="intro" label="Nội dung giới thiệu" :value="$service->intro" rows="7" /><x-textarea name="benefits" label="Điểm nổi bật, mỗi dòng một ý" :value="implode(PHP_EOL, $service->benefits ?: [])" rows="6" /></x-card><x-card type="secondary" title="SEO"><x-input name="seo_title" label="SEO title" :value="$service->seo_title" /><x-textarea name="seo_description" label="SEO description" :value="$service->seo_description" rows="3" /></x-card></div><div class="col-xl-4"><x-card type="info" title="Phân loại & hiển thị"><x-select name="service_category_id" label="Danh mục" :options="$categories->pluck('name', 'id')->all()" :selected="old('service_category_id', $service->service_category_id)" required /><x-input name="icon" label="Bootstrap icon" :value="$service->icon" placeholder="bi-compass" /><x-image-upload name="cover_image" label="Ảnh cover" :value="$service->cover_image" /><x-input name="sort_order" type="number" label="Thứ tự" :value="$service->sort_order ?: 0" /><label class="form-check form-switch"><input class="form-check-input" type="checkbox" name="is_active" value="1" @checked(old('is_active', $service->exists ? $service->is_active : true))><span class="form-check-label">Kích hoạt</span></label></x-card></div><div class="col-12 text-end"><a href="{{ route('admin.services.index') }}" class="btn btn-default">Hủy bỏ</a> <button class="btn btn-primary">{{ $submitLabel }}</button></div></div>
